import{_ as a,o as r,c as o,a2 as i}from"./chunks/framework.BXzK3EA4.js";const f=JSON.parse('{"title":"浏览器原理","description":"7 年前端面试必问。简历里写\\"性能优化\\"、\\"PWA\\"、\\"首屏优化\\"都需要浏览器原理支撑。本文按\\"输入 URL 到页面渲染\\"主线展开，配真实代码和项目经验。","frontmatter":{},"headers":[],"relativePath":"browser/index.md","filePath":"browser/index.md","lastUpdated":1793932732000}'),t={name:"browser/index.md"};function l(c,e,s,d,n,h){return r(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="浏览器原理" tabindex="-1">浏览器原理 <a class="header-anchor" href="#浏览器原理" aria-label="Permalink to &quot;浏览器原理&quot;">​</a></h1><blockquote><p>7 年前端面试必问。简历里写&quot;性能优化&quot;、&quot;PWA&quot;、&quot;首屏优化&quot;都需要浏览器原理支撑。本文按&quot;输入 URL 到页面渲染&quot;主线展开，配真实代码和项目经验。</p></blockquote><h2 id="📚-章节列表" tabindex="-1">📚 章节列表 <a class="header-anchor" href="#📚-章节列表" aria-label="Permalink to &quot;📚 章节列表&quot;">​</a></h2><ol><li><a href="./1-architecture">浏览器架构</a></li><li><a href="./2-url-to-page">输入 URL 到页面渲染全过程</a></li><li><a href="./3-event-loop">浏览器事件循环（与 JS 的区别）</a></li><li><a href="./4-cache">强缓存 vs 协商缓存</a></li><li><a href="./5-storage">浏览器存储</a></li><li><a href="./7-render">浏览器渲染流程（重要！）</a></li><li><a href="./8-web-vitals">Web Vitals（性能核心指标）</a></li><li><a href="./9-threads">浏览器线程与异步</a></li><li><a href="./10-service-worker">Service Worker 与 PWA</a></li><li><a href="./11-tab-communication">跨标签页通信</a></li><li><a href="./12-security">浏览器安全模型</a></li><li><a href="./14-project-pitfalls">项目踩过的坑</a></li><li><a href="./15-further-reading">推荐深入</a></li></ol><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>浏览器专题沿「<strong>输入 URL → 解析 → 请求 → 渲染 → 缓存 → 存储 → 线程 → SW</strong>」一条主线展开,顺序本身就是知识结构。</li><li>必须能默画的三张图:浏览器多进程架构图、渲染流水线图、HTTP 缓存决策图。</li><li>缓存是面试重灾区:强缓存/协商缓存、<code>Cache-Control</code> 各指令、<code>Vary</code>、<code>ETag/If-None-Match</code> 的完整链路。</li><li>事件循环要能区分<strong>任务队列与微任务队列</strong>,并说清 <code>Promise</code>/<code>MutationObserver</code>/<code>queueMicrotask</code> 属于微任务。</li><li>渲染优化要从「重排 vs 重绘 vs 合成」讲起,再落到 <code>transform/opacity</code>、批量读写、虚拟列表。</li><li>Service Worker 与 PWA 要能讲清缓存策略选择与版本更新流程,这是区分「用过」和「懂原理」的分水岭。</li></ul>',6)])])}const _=a(t,[["render",l]]);export{f as __pageData,_ as default};
